#!/usr/bin/env node
// Generated by gadriel-cli — DO NOT EDIT BY HAND.
// Re-run `gadriel code init --upgrade` to refresh.
//
// Gadriel Claude Code hook dispatcher.
//
// Contract (matches docs/architecture/_real-test-rollout-plan.md §1.5.e and §1.5.f):
//   - First argv is the subcommand: pre-bash | post-edit | route |
//     session-restore | snapshot-load | session-end | sync |
//     compact-manual | compact-auto | post-task
//   - Reads a JSON event payload from stdin within 500ms (defaults to {}).
//   - Each handler is wrapped in try/catch and is allowed at most 3000ms.
//   - The entire process is hard-killed at 5000ms global elapsed (process.exit(0)).
//   - Every code path returns exit code 0. This script MUST NEVER crash a hook.
//   - All diagnostic output is appended to .security/audit/audit-log.jsonl —
//     stdout/stderr stay silent so Claude Code's hook channel stays clean.

'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const STARTED_AT = Date.now();
const GLOBAL_BUDGET_MS = 5000;
const HANDLER_BUDGET_MS = 3000;
const STDIN_BUDGET_MS = 500;

// Hard global timeout. If anything below blocks past 5s, we exit 0 silently.
const globalTimer = setTimeout(() => {
  try {
    safeAudit({ event: 'hook_global_timeout', subcommand: process.argv[2] || 'unknown' });
  } catch (_) { /* swallow */ }
  process.exit(0);
}, GLOBAL_BUDGET_MS);
globalTimer.unref();

// BUG-017 defensive parity with the Rust handler: treat the literal
// placeholder `"${CLAUDE_PROJECT_DIR}"` as if the env var were unset
// so an upstream tool's leaked `env:` value can never spawn a real
// `${CLAUDE_PROJECT_DIR}/` directory in the repo root.
function pickProjectRoot() {
  const candidates = [process.env.CLAUDE_PROJECT_DIR, process.env.GADRIEL_PROJECT_ROOT];
  for (const c of candidates) {
    if (typeof c === 'string' && c !== '' && c !== '${CLAUDE_PROJECT_DIR}') {
      return c;
    }
  }
  return process.cwd();
}

// Audit-log helper — silent on any failure.
function safeAudit(record) {
  try {
    const root = pickProjectRoot();
    const auditDir = path.join(root, '.security', 'audit');
    const auditFile = path.join(auditDir, 'audit-log.jsonl');
    fs.mkdirSync(auditDir, { recursive: true });
    const line = JSON.stringify({
      ts: new Date().toISOString(),
      elapsed_ms: Date.now() - STARTED_AT,
      ...record,
    });
    fs.appendFileSync(auditFile, line + '\n');
  } catch (_) {
    // Never let an audit failure escape — hooks must stay invisible.
  }
}

// Read stdin with a 500ms hard cap; resolve to '' if nothing arrives.
function readStdinWithTimeout(ms) {
  return new Promise((resolve) => {
    let resolved = false;
    let buf = '';
    const done = (val) => {
      if (resolved) return;
      resolved = true;
      resolve(val);
    };
    const timer = setTimeout(() => done(buf), ms);
    timer.unref();
    try {
      if (process.stdin.isTTY) {
        // No payload coming over a TTY.
        clearTimeout(timer);
        return done('');
      }
      process.stdin.setEncoding('utf8');
      process.stdin.on('data', (chunk) => {
        buf += chunk;
        if (buf.length > 64 * 1024) {
          // Bound the payload — hooks shouldn't be megabytes.
          clearTimeout(timer);
          done(buf.slice(0, 64 * 1024));
        }
      });
      process.stdin.on('end', () => {
        clearTimeout(timer);
        done(buf);
      });
      process.stdin.on('error', () => {
        clearTimeout(timer);
        done(buf);
      });
    } catch (_) {
      clearTimeout(timer);
      done('');
    }
  });
}

function parsePayload(raw) {
  if (!raw) return {};
  try { return JSON.parse(raw); } catch (_) { return {}; }
}

// Shell out to `gadriel hooks <subcmd> --json` with a 3s timeout. Returns the
// subprocess result (or null on failure) — never throws.
function callGadriel(subcommand, payload) {
  try {
    const args = ['hooks', subcommand, '--json'];
    const input = JSON.stringify(payload || {});
    const result = spawnSync('gadriel', args, {
      input,
      timeout: HANDLER_BUDGET_MS,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return result || null;
  } catch (_) {
    return null;
  }
}

// Run a handler under both a try/catch and a soft per-handler clock. If the
// handler itself respects the 3s spawn timeout there's nothing more to do;
// this just records the outcome.
async function runHandler(subcommand, payload, fn) {
  const t0 = Date.now();
  try {
    await fn(payload);
    safeAudit({
      event: 'hook_ok',
      subcommand,
      handler_ms: Date.now() - t0,
    });
  } catch (err) {
    safeAudit({
      event: 'hook_error',
      subcommand,
      handler_ms: Date.now() - t0,
      error: err && err.message ? String(err.message).slice(0, 500) : 'unknown',
    });
  }
}

// ---------------------------------------------------------------------------
// Handlers — each one is intentionally tiny: shell out to `gadriel hooks ...`
// and let the Rust binary do the real work. If gadriel isn't installed yet,
// the shim script already swallowed that case; here we just record the miss.
// ---------------------------------------------------------------------------

function makeShellHandler(subcmd) {
  return async (payload) => {
    const res = callGadriel(subcmd, payload);
    if (!res || res.error) {
      safeAudit({ event: 'gadriel_missing', subcommand: subcmd });
      return;
    }
    if (res.status !== 0) {
      safeAudit({
        event: 'gadriel_nonzero',
        subcommand: subcmd,
        status: res.status,
        stderr: (res.stderr || '').slice(0, 500),
      });
    }
  };
}

const HANDLERS = {
  'pre-bash':        makeShellHandler('pre-bash'),
  'post-edit':       makeShellHandler('post-edit'),
  'route':           makeShellHandler('route'),
  'session-restore': makeShellHandler('session-restore'),
  'snapshot-load':   makeShellHandler('snapshot-load'),
  'session-end':     makeShellHandler('session-end'),
  'sync':            makeShellHandler('sync'),
  'compact-manual':  makeShellHandler('compact-manual'),
  'compact-auto':    makeShellHandler('compact-auto'),
  'post-task':       makeShellHandler('post-task'),
};

async function main() {
  const subcommand = process.argv[2] || '';
  const handler = HANDLERS[subcommand];

  if (!handler) {
    safeAudit({ event: 'hook_unknown', subcommand });
    return;
  }

  const raw = await readStdinWithTimeout(STDIN_BUDGET_MS);
  const payload = parsePayload(raw);

  await runHandler(subcommand, payload, handler);
}

// Top-level guard — anything that escapes still exits 0.
main()
  .then(() => {
    clearTimeout(globalTimer);
    process.exit(0);
  })
  .catch((err) => {
    try {
      safeAudit({
        event: 'hook_fatal',
        subcommand: process.argv[2] || 'unknown',
        error: err && err.message ? String(err.message).slice(0, 500) : 'unknown',
      });
    } catch (_) { /* swallow */ }
    clearTimeout(globalTimer);
    process.exit(0);
  });
